      "steps": [
        "W małej miseczce dokładnie mieszamy miód, musztardę, sok z cytryny oraz pieprz , aż uzyskamy jednolitą konsystencję.",
        "Plastry ananasa wyjmujemy z zalewy i bardzo dokładnie osuszamy ręcznikiem papierowym (dzięki temu grzanki nie będą rozmoczone w środku). Każdy plaster możemy przekroić na pół, aby lepiej wypełnił chleb. Ser mozzarellę kroimy na cienkie plastry.",
        "Kromki chleba smarujemy z jednej strony przygotowanym sosem musztardowym. Nieparzystą kromkę przekrawamy na pół.",
        "Na połowie pieczywa (na stronie z sosem) układamy kolejno: szynkę z kurczaka, ananasa, ser mozzarellę oraz rukolę. Całość przykrywamy pozostałym pieczywem (stroną z sosem do wewnątrz), tworząc zamknięte kanapki.",
        "Patelnię grillową rozgrzewamy na średnim ogniu i rozprowadzamy oliwę za pomocą pędzelka silikonowego.",
        "Kładziemy kanapki na patelni i smażymy przez około 2–3 minuty z każdej strony, dociskając je lekko łopatką. Smażymy do czasu, aż chleb stanie się złocisty i chrupiący (z charakterystycznymi paskami od grilla), a ser wewnątrz całkowicie się rozpuści.",
        "Gotowe grzanki przekładamy na talerz i podajemy od razu na ciepło."
      ],
