      "steps": [
        "Ser ścieramy na tarce o grubych oczkach (dzięki temu szybciej się rozpuści). Pomidora kroimy w plasterki.",
        "W miseczce rozkłócamy jajka widelcem. Dodajemy sól, pieprz oraz zioła prowansalskie, dokładnie mieszamy.",
        "Na patelni o średnicy zbliżonej do wielkości tortilli rozgrzewamy oliwę na średnim ogniu. Układamy plastry szynki i podsmażamy je przez około 1 minutę.",
        "Całość zalewamy masą jajeczną, starając się rozprowadzić ją równomiernie po dnie patelni. Smażymy przez ok. 1-2 minuty, aż spód się zetnie, ale wierzch będzie jeszcze lekko płynny.",
        "Na wciąż wilgotne jajka kładziemy tortillę i lekko dociskamy ją dłonią lub łopatką, aby przykleiła się do masy jajecznej. Smażymy jeszcze przez chwilę (ok. 30 sekund).",
        "Zdecydowanym ruchem (używając szerokiej łopatki) przewracamy całość na drugą stronę – tak, aby tortilla znalazła się na dnie patelni, a jajka z dodatkami na górze.",
        "Na gorącym omlecie posypujemy ser. Zmniejszamy ogień do minimum i czekamy chwilę, aż tortilla od spodu stanie się chrupiąca, a ser zacznie się topić.",
        "Zdejmujemy patelnię z ognia. Na wierzch układamy pomidora oraz rukolę. Całość składamy na pół (tworząc półksiężyc) i przekładamy na talerz."
      ],
      "sourceFile": "Dieta-posiłki (19).pdf",
