      "steps": [
        "Jajka gotujemy na twardo przez 7 minut (czas liczony od zagotowania wody).",
        "Botwinkę kroimy w całości: buraczki w drobną kostkę, listki siekamy. Ziemniaki również kroimy w kostkę.",
        "Cebulę oraz czosnek drobno siekamy.",
        "W garnku rozgrzewamy oliwę. Wrzucamy ziemniaki, cebulę oraz czosnek, całość podsmażamy przez 5 minut.",
        "Do garnka wlewamy bulion, doprowadzamy do wrzenia i gotujemy zawartość przez ok. 8-10 minut w zależności od grubości kostki ziemniaków. Gdyby bulion za bardzo odparował, stopniowo dolewamy wodę podczas gotowania.",
        "Po tym czasie dodajemy botwinkę i gotujemy wszystko przez kolejne 5 minut. Sprawdzamy, czy buraczki są miękkie, w razie potrzeby gotujemy jeszcze kilka minut. Zupę doprawiamy sokiem z cytryny, solą oraz pieprzem , dokładnie mieszamy.",
        "Do miseczki przekładamy jogurt, dodajemy 2-3 łyżki zupy, dokładnie mieszamy, następnie dodajemy kolejne 2-3 łyżki bulionu, mieszamy i dodajemy rozrobiony jogurt do zupy. Zawartość garnka jeszcze raz dokładnie mieszamy.",
        "Gotową zupę przekładamy do talerza i podajemy z jajkami. Danie posypujemy posiekanym koperkiem."
      ],
