      "steps": [
        "Makaron gotujemy wg instrukcji na opakowaniu. Pozostawiamy ok. 100 ml wody z gotowania makaronu.",
        "Krewetki umieszczamy w miseczce i marynujemy (marynata: mieszamy oliwę, sok z cytryny, przeciśnięty przez praskę czosnek, sól oraz pieprz ) przez kilka minut. W przypadku mrożonych krewetek należy je wcześniej rozmrozić. Jeśli mamy świeże krewetki, usuwamy głowę, pancerzyk, odnóża i na końcu nacinamy grzbiet i pozbywamy się jelitka. Ogony pozostawiamy, gdyż nadają sporo aromatu potrawie.",
        "Cukinię obieramy i kroimy na cienkie plastry.",
        "Krewetki smażymy na rozgrzanej patelni na złoty kolor. Zdejmujemy z patelni.",
        "Na tej samej patelni podsmażamy cukinię przez 3-4 minuty (na złoty kolor, ale żeby się nie rozpadała).",
        "Makaron mieszamy z cukinią i krewetkami. Dodajemy wodę z gotowania makaronu (wedle uznania) i podsmażamy przez chwilę.",
        "Przed podaniem posypujemy natką pietruszki."
      ],
