      "steps": [
        "W garnku zagotowujemy wodę z odrobiną soli.",
        "Jabłko obieramy, usuwamy gniazdo nasienne i kroimy w cienkie półplasterki.",
        "Rozgrzewamy patelnię na średniej mocy palnika, dodajemy masło i wrzucamy pokrojone jabłko.",
        "Smażymy bez przykrycia przez około 3–4 minuty, aż zmiękną, a następnie skrapiamy je sokiem z cytryny i posypujemy erytrolem oraz cynamonem.",
        "Kopytka gotujemy we wrzącej wodzie według instrukcji na opakowaniu.",
        "W małej miseczce rozgniatamy ser twarogowy widelcem, mieszamy go z jogurtem naturalnym na jednolitą masę.",
        "Odcedzamy kopytka na sicie i przekładamy je bezpośrednio na patelnię z ciepłymi owocami. Delikatnie mieszamy kopytka z owocami, aby oblepiły się syropem.",
        "Przekładamy danie na talerz, a na wierzchu układamy ser twarogowy."
      ],
