        "Kurczaka przecinamy wzdłuż, tak aby uzyskać plastry o podobnej grubości. Przekładamy do miski i dodajemy do nich mieszankę cajun i oliwę (połowa), mieszamy i odstawiamy na minimum 15 minut.",
