      "steps": [
        "Pesto przygotowujemy wg przepisu po kliknięciu w czapkę kucharską, znajdującą się po prawej stronie składnika: Pesto pietruszkowe z chilli.",
        "Makaron gotujemy zgodnie z instrukcją na opakowaniu. Odcedzamy i odstawiamy na bok. Pozostawiamy 2-3 łyżki wody z gotowania makaronu.",
        "Indyka kroimy w plastry o grubości około 1 cm, a następnie doprawiamy solą, pieprzem , oregano oraz słodką papryką według własnego uznania.",
        "Na patelni rozgrzewamy oliwę z oliwek na średnim ogniu i układamy plastry mięsa. Smażymy je przez około 3-4 minuty z każdej strony, aż mięso stanie się złociste z zewnątrz i całkowicie usmażone w środku (o jasnym kolorze w przekroju).",
        "Pomidorki koktajlowe kroimy na mniejsze kawałki i dorzucamy na patelnię do usmażonego mięsa. Smażymy przez 2 minuty, do puszczenia soku, zmięknięcia i zrumienienia pomidorków koktajlowych.",
        "Ugotowany makaron wrzucamy bezpośrednio na patelnię z mięsem i pomidorkami koktajlowymi.",
        "Dodajemy pesto z natki pietruszki oraz zachowaną wodę z makaronu. Całość trzymamy na małym ogniu przez około 1-2 minuty, energicznie mieszając, aby pesto dokładnie połączyło się z pozostałymi składnikami.",
        "Danie doprawiamy (najlepiej świeżo zmielonym) i opcjonalnie solą po spróbowaniu (uważamy na ilość dodawanej soli, ponieważ pesto już jest słone).",
        "Przekładamy danie na talerz, posypujemy startym parmezanem. Całość dekorujemy świeżymi listkami bazylii świeżej."
      ],
