      "steps": [
        "Makaron gotujemy według instrukcji na opakowaniu. Odcedzamy i odstawiamy.",
        "Cukinię obieramy obieraczką na cienkie, długie plasterki. Paprykę czerwoną kroimy w cienkie paski lub średniej wielkości kostkę. Czosnek drobno siekamy. Łososia dzielimy na mniejsze kawałki. Pomidorki koktajlowe kroimy na mniejsze kawałki.",
        "Na średnim ogniu rozgrzewamy oliwę. Podsmażamy czosnek przez ok. minutę do lekkiego zrumienienia. Następnie dodajemy paprykę czerwoną oraz cukinię, całość podsmażamy przez ok. 5-10 minut do zmięknięcia warzyw.",
        "Kiedy warzywa zmiękną, zalewamy całość mleczkiem kokosowym. Gdy mleczko kokosowe zacznie bulgotać, zmniejszamy moc palnika, dodajemy łososia i gotujemy bez przykrycia przez około 10 minut.",
        "Jeśli po tym czasie zostanie zbyt dużo płynu, zwiększamy moc palnika, aby odparować jego nadmiar. Jeśli natomiast sos zbyt szybko odparuje, dodajemy odrobinę gorącej wody.",
        "Pod koniec gotowania dodajemy makaron oraz pomidorki koktajlowe. Doprawiamy w tym czasie solą, pieprzem, sokiem z cytryny oraz oregano. Całość smażymy jeszcze przez około 3 minuty.",
        "Gotowe danie przekładamy na talerz. Przed podaniem posypujemy natką pietruszki."
      ],
