        "Jajko rozkłócamy w misce za pomocą widelca.",
        "Na patelni rozgrzewamy olej, wlewamy jajko i smażymy je jak omlet. Jeśli omlet nam się przerwie czy rozpadnie, nic nie szkodzi. Gotowe jajko przekładamy na talerz.",
        "Na tej samej patelni podsmażamy krewetki do zarumienienia z każdej strony przez ok. 5-7 minut. Podsmażone krewetki przenosimy na talerz.",
