        "Następnie na patelnię dodajemy krewetki, kiełki, omlet jajeczny oraz posiekane orzechy, dolewamy pozostały sos i wszystko dokładnie mieszamy. Całość przesmażamy razem przez 2-3 minuty.",
        "Gotowe danie przekładamy na talerz. Opcjonalnie posypujemy danie posiekaną kolendrą świeżą."
