        "Wkładamy również pomidorki koktajlowe pokrojone na mniejsze kawałki. Następnie: posypujemy serem mozzarellą żółtą, układamy plasterki sera mozzarelli, a na koniec dokładamy serek śmietankowy. Nie mieszamy składników, a serek nakładamy po łyżce w różnych miejscach zapiekanki.",
        "Zapiekankę pieczemy w rozgrzanym piekarniku przez ok. 30 minut. Gdyby wierzch zapiekanki zbyt mocno się przypiekał, wycinamy prostokąt papieru do pieczenia i delikatnie przykrywamy zapiekankę.",
