        "Awokado obieramy i kroimy w kostkę lub plasterki.",
        "Podgrzewamy tortillę, układamy kolejno awokado, warzywa oraz kurczaka. Posypujemy startą na tarce o grubych oczkach serem mozzarellą oraz kolendrą świeżą.",
        "Składamy tortillę na pół, przekładamy na patelnię i podpiekamy do czasu rozpuszczenia się sera mozzarelli."
