        "Na patelni rozgrzewamy oliwę na średnim ogniu. Następnie smażymy mięso, aż będzie miękkie i zarumienione. Po ok. 8 minutach nacinamy najgrubszy kawałek i sprawdzamy, czy mięso ma jasny kolor w środku. Gotowe mięso odstawiamy do wystygnięcia.",
