      "steps": [
        "Komosę ryżową przygotowujemy zgodnie z instrukcją na opakowaniu.",
        "Ogórka myjemy i kroimy na bardzo cienkie plasterki. Możemy użyć do tego mandoliny.",
        "Łososia wędzonego tniemy na mniejsze, nieregularne kawałki.",
        "W małej miseczce przygotowujemy sos. Łączymy jogurt skyr, majonez, czosnek granulowany, sól oraz pieprz . Mieszamy, aż sos będzie gładki. Koperek drobno siekamy i dodajemy do sosu, mieszając.",
        "Na talerzu układamy schłodzoną komosę. Na niej układamy plasterki ogórka, a następnie kawałki ryby.",
        "Całość polewamy przygotowanym sosem koperkowym.",
        "Podajemy z plasterkami cytryny, którą możemy skropić sałatkę tuż przed jedzeniem."
      ],
