      "steps": [
        "Ryż gotujemy zgodnie z instrukcją na opakowaniu. Ryż nie gotujemy do miękkości, pozostawiamy al dente (lekko twardawe). Następnie odcedzamy i odstawiamy.",
        "Kurczaka kroimy w cienkie paski (ok. 1 cm grubości). Brokuła kroimy na drobniejsze kawałki. Marchew obieramy i kroimy w cienkie kawałki.",
        "Imbir oraz czosnek obieramy i drobno siekamy. Papryczkę chilli kroimy w bardzo cienkie plasterki.",
        "Na dużej patelni lub woku rozgrzewamy oliwę na dużym ogniu. Wrzucamy kawałki kurczaka i smażymy bez przykrycia, mieszając, aż kurczak się zrumieni z każdej strony.",
        "Dodajemy imbir, papryczkę chilli oraz czosnek, smażymy przez około minutę, cały czas mieszając.",
        "Dodajemy brokuła oraz marchew, smażymy przez 2–3 minuty do zmięknięcia warzyw, co chwilę mieszamy. Jeśli warzywa nie chcą zmięknąć, dolewamy odrobinę ciepłej wody, zmniejszamy moc palnika na średnią, przykrywamy patelnię częściowo i gotujemy jeszcze 2–3 minuty do lekkiego zmięknięcia warzyw.",
        "Na koniec smażenia, dodajemy ryż oraz sos sojowy według własnego uznania, całość dokładnie mieszamy i smażymy jeszcze 3- 4 minuty na średnim ogniu, bez przykrycia, aż składniki dobrze się połączą.",
        "Gotowe danie przekładamy na talerz i podajemy z sezamem ."
      ],
