      "steps": [
        "Kurczaka kroimy w drobną kostkę, doprawiamy solą, pieprzem , słodką papryką oraz czosnkiem granulowanym.",
        "Na małej patelni rozgrzewamy oliwę (połowa), wrzucamy kurczaka i smażymy na średnim ogniu przez ok. 7–8 minut, aż mięso się zarumieni i będzie usmażone w środku (po nacięciu powinno mieć jasny kolor). Odstawiamy.",
        "Cebulę oraz natkę pietruszki drobno siekamy. Czosnek przeciskamy przez praskę. Seler naciowy kroimy na cienki plasterki.",
        "W garnku rozgrzewamy na małym ogniu pozostałą ilość oliwy. Dodajemy drobno pokrojoną cebulę i smażymy przez 4–5 minut, aż się zeszkli. Dodajemy przeciśnięty przez praskę czosnek i smażymy jeszcze 30 sekund.",
        "Wrzucamy seler naciowy i smażymy 3–4 minuty, mieszając. Następnie wlewamy bulion warzywny i gotujemy na małym ogniu, pod częściowym przykryciem, przez 15 minut – aż seler naciowy zmięknie.",
        "Wyłączamy palnik i blendujemy zupę na gładki krem. Po zblendowaniu ponownie włączamy moc palnika na małą. Przyprawiamy solą, pieprzem oraz tymiankiem suszonym wedle uznania. Gotujemy całość przez chwilę, aby zupa nabrała smaku i aromatu.",
        "Jeśli zupa jest zbyt gęsta, dolewamy niewielką ilość gorącej wody i mieszamy do uzyskania pożądanej konsystencji. Jeśli jest zbyt rzadka, zwiększamy moc palnika i gotujemy chwilę bez przykrycia, aż część płynu odparuje.",
        "Do jogurtu greckiego dodajemy 2-3 łyżki zupy i energicznie mieszamy, następnie wlewamy całość do zupy i mieszamy do połączenia. Wyłączamy palnik.",
        "Pieczywo możemy podsmażyć na suchej patelni, na średnim ogniu lub podpiec w opiekaczu do zrumienienia.",
        "Podajemy zupę z usmażonym kurczakiem i pieczywem. Na koniec posypujemy natką pietruszki."
      ],
