        "W osobnym garnku gotujemy bób: zalewamy wodą dwa razy więcej niż objętość bobu, solimy lekko i gotujemy pod przykryciem na średnim ogniu przez 8–10 minut, aż będzie miękki. Po ugotowaniu odcedzamy i obieramy z łupin.",
