      "steps": [
        "Do małego garnka wlewamy napój i wsypujemy płatki. Stawiamy na średnim ogniu i doprowadzamy do wrzenia. Zmniejszamy płomień na minimum i gotujemy płatki przez około 5–8 minut, dość często mieszając, aby owsianka nie przypaliła się do dna. Płatki powinny wchłonąć większość płynu i stać się miękkie oraz kremowe. Jeśli płatki wchłoną zbyt mało płynu, zwiększamy moc palnika i gotujemy do odparowania nadmiaru płynu.",
        "Zdejmujemy garnek z ognia. Odczekujemy około minuty, a następnie dodajemy odżywkę białkową i bardzo energicznie mieszamy. Jeśli masa wydaje się zbyt gęsta, możemy dolać odrobinę gorącej wody lub dodatkowego napoju. Dosładzamy owsiankę erytrolem według własnego uznania.",
        "Jabłko kroimy w dowolne kawałki - mogą to być grubsze plastry lub kostka.",
        "Gotową owsiankę przekładamy do miski. Na wierzchu układamy przygotowane owoce. Całość polewamy masłem orzechowym."
      ],
