        "Owoce przekrajamy na połówki, usuwamy pestkę i układamy na blaszce wyłożonej papierem do pieczenia. W przypadku większych owoców możemy podzielić je jeszcze na mniejsze kawałki.",
        "Na owocach rozprowadzamy masło. Masło możemy wcześniej delikatnie podgrzać do rozpuszczenia i rozprowadzić je za pomocą pędzelka kuchennego. Na koniec posypujemy owoce cynamonem.",
