      "steps": [
        "Do garnka o grubym dnie wlewamy mleko. Wrzucamy szczyptę soli. Garnek stawiamy na średniej mocy palnika i podgrzewamy do momentu, aż mleko się zagotuje. Wsypujemy płatki ryżowe.",
        "Gdy mleko zacznie się gotować, zmniejszamy moc palnika na małą. Gotujemy płatki na małej mocy palnika, bez przykrycia, przez około 5 minut, bardzo często i delikatnie mieszając (co około 1-2 minuty), aby płatki nie przywarły do dna.",
        "Po 5 minutach dodajemy miód oraz ekstrakt waniliowy. Mieszamy. Kontynuujemy gotowanie przez kolejne 1-3 minuty, stale mieszając, aż płatki wchłoną większość mleka i staną się miękkie. Ryżanka jest gotowa, gdy ma konsystencję gęstej kaszki. Gdy płatki odrobinę ostygną, dodajemy jogurt skyr i mieszamy.",
        "Podczas gdy ryż się gotuje, przygotowujemy śliwki. śliwki myjemy, kroimy na połówki i usuwamy pestki. Większe połówki możemy dodatkowo przekroić na ćwiartki.",
        "Na małej patelni rozgrzewamy miód na średniej mocy palnika. Dodajemy owoce. Smażymy przez około 5-8 minut, delikatnie mieszając, aż zmiękną, puszczą sok i pokryją się sosem. Jeśli zaczną przywierać do patelni, dodajemy odrobinę wody. Powinny pozostać w całości, ale być widocznie miękkie.",
        "Zdejmujemy z palnika i dodajemy cynamon. Mieszamy delikatnie.",
        "Ugotowaną ryżankę przekładamy do miseczek. Na wierzch układamy ciepłe, duszone owoce wraz z powstałym sosem. Przed podaniem posypujemy posiekanymi orzechami."
      ],
