      "steps": [
        "Wyjmujemy mrożone truskawki z zamrażarki bezpośrednio przed przygotowaniem, aby pozostały twarde i mocno schłodzone, co pozwoli uzyskać gęstą konsystencję deseru. Orzechy nerkowca siekamy.",
        "Wlewamy do wysokiego naczynia blendera mleko oraz napój mleczny. Dodajemy mrożone owoce, banana oraz połowę mięty.",
        "Blendujemy wszystkie składniki na dużej mocy urządzenia przez około 60–90 sekund, aż masa stanie się całkowicie gładka, bardzo gęsta i przypominająca półpłynne lody.",
        "Przelewamy przygotowaną bazę do szerokiej miski, wygładzając wierzch łyżką. Wysypujemy na jedną stronę miski granolę, a na drugiej układamy świeże truskawki. Całość posypujemy orzechy nerkowca i pozostałymi listkami mięty.",
        "Spożywamy bowl natychmiast po przygotowaniu, ponieważ mrożone owoce szybko zmieniają konsystencję na rzadszą. Jeśli po zblendowaniu masa jest zbyt płynna, możemy włożyć bowla do zamrażarki, do lekkiego zmrożenia."
      ],
